        report.put("final_exact_finite_ledger",Map.of("actual_paid_crafts",1,"actual_centivis_price",PRICE,"actual_total_native_wand_gains",Map.copyOf(ledger.gains),"actual_gold7_RAW_snbt",snbt(finalGold,player),"actual_stabilizer_owners",1,"same_native_drop_UUID",dropId.toString(),"saved_pick_damage1_to2",true,"actual_saved_typed_crystals",typedStock(player.getInventory().items),"native_SERVER_POST_checks",ledger.checks,"vis_XP_stock_or_output_grants",0));
        report.put("final_native_node_state",Map.of("target",nodeState(frame.target(),frame.tick()),"OTHER_recipe_source",nodeState(frame.source(),frame.tick()),"actual_powered_stale_cache_POSTs",ledger.stalePowered,"actual_unpowered_stale_cache_POSTs",ledger.staleUnpowered,"actual_cached_lock_transitions",ledger.lockTransitions,"actual_FULL_locked_interval_ticks",1200,"at600_regained",0,"at1200_regained",1,"forced_random_choice_or_timer_writes",0));
        report.put("next_save_inputs",Map.of("bench",bench.toShortString(),"old_center",center.toShortString(),"target_node",targetPos.toShortString(),"OTHER_charge_source",sourcePos.toShortString(),"actual_installed_stabilizer",devicePos.toShortString(),"actual_support",supportPos.toShortString(),"actual_lever_off",leverPos.toShortString(),"stabilizer_RAW_snbt",beTag(player.level().getBlockEntity(devicePos)).toString(),"transient_warning","Node count/lock/regeneration and client animation are NOT persisted. Native load/poll/catch-up remain real; do not freeze/reset them. Node current gains are actual, not a golden future baseline. All original87 non-node BEs unchanged except ONLY empty1882 valve natural suction amount poll; no furnace clock exceptions. New bench+stabilizer =2BE, expected89 requires independent root stopped audit."));
        report.put("retained_prior_workshop",Map.of("old_non_node_BEs",87,"old_jars_units",List.of(20,333),"old_candles",72,"old_furnace_clock_exceptions",0,"saved_four_typed_crystals_and_both8phials",true,"all_old_wands_foci_gear_apple_XP11_knowledge",true,"old_world_pressure_exception_ONLY",oldValvePosition().toShortString(),"full_VisNet_advanced_special_audio_parity_claim",false));finalVerified=true;
