    private static BlockPos oldValvePosition(){return new BlockPos(1882,218,377);}

    private BlockPos patchMin(){return bench.offset(-4,-2,-6);}
    private BlockPos patchMax(){return bench.offset(7,7,6);}
    private AABB patchBounds(){return new AABB(Vec3.atLowerCornerOf(patchMin()),Vec3.atLowerCornerOf(patchMax().offset(1,1,1)));}
    private AABB targetBounds(){return new AABB(Vec3.atLowerCornerOf(targetPos.offset(-7,-4,-7)),Vec3.atLowerCornerOf(targetPos.offset(8,5,8)));}
    private boolean ownedPosition(Vec3 pos){return patchBounds().contains(pos) || targetBounds().contains(pos);}
    private void patch(ServerLevel level){for(int x=patchMin().getX()>>4;x<=patchMax().getX()>>4;x++)for(int z=patchMin().getZ()>>4;z<=patchMax().getZ()>>4;z++)level.getChunk(x,z);require(level.getEntitiesOfClass(ItemEntity.class,patchBounds()).isEmpty() && level.getEntitiesOfClass(ExperienceOrb.class,patchBounds()).isEmpty() && level.getEntitiesOfClass(LivingEntity.class,patchBounds()).isEmpty() && level.getEntitiesOfClass(ItemEntity.class,targetBounds()).isEmpty() && pendingStacks(level).isEmpty(),"NEW bench patch refuses old entities/items/pending, no clearing old target area");for(BlockPos pos:BlockPos.betweenClosed(patchMin(),patchMax()))require(!oldBlocks.containsKey(pos) && level.getBlockEntity(pos)==null && !BuiltInRegistries.BLOCK.getKey(level.getBlockState(pos).getBlock()).getNamespace().equals("thaumcraft"),"never overwrite old/TC/BE cell "+pos);for(BlockPos pos:BlockPos.betweenClosed(patchMin(),patchMax()))level.setBlockAndUpdate(pos,pos.getY()<bench.getY()?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState());}
    private int supply(ServerPlayer player,Item item,int n,String purpose){require((item==Items.GOLD_INGOT || item==Items.PISTON || item==Items.STONE || item==Items.LEVER || item==material("nitor")) && n==1 || (item==Items.QUARTZ_BLOCK || item==bricks()) && n==2,"ONLY exact declared raw / explicit pre-crafted recipe ingredients, no finished stabilizer or stock grant");int slot=emptyMain(player);player.getInventory().setItem(slot,new ItemStack(item,n));inputs.add(Map.of("declared_item",BuiltInRegistries.ITEM.getKey(item).toString(),"actual_count",n,"purpose",purpose,"genuinely_empty_main_slot",slot,"already_crafted_ingredient_NOT_acquired_here",item==material("nitor") || item==bricks()));return slot;}
    private List<ItemStack> physicalStacks(ServerPlayer player){var out=new ArrayList<ItemStack>();out.addAll(player.getInventory().items);out.addAll(player.getInventory().offhand);out.add(player.containerMenu.getCarried());TileArcaneWorkbench table=table(player.level());for(int i=0;i<9;i++)out.add(table.getItem(i));out.add(table.getItem(TileArcaneWorkbench.WAND_SLOT));for(ItemEntity item:player.serverLevel().getEntitiesOfClass(ItemEntity.class,patchBounds()))out.add(item.getItem());for(ItemEntity item:player.serverLevel().getEntitiesOfClass(ItemEntity.class,targetBounds()))out.add(item.getItem());out.addAll(pendingStacks(player.serverLevel()));return out;}
    /** Pure final-M06e queue view, NOT save(): save may acknowledge in-flight
     * physical admission. No flush/accept/reconcile/stock/time/RNG callbacks. */
    @SuppressWarnings("unchecked") private List<ItemStack> pendingStacks(ServerLevel level){try{var field=DeferredItemDrops.class.getDeclaredField("FACTORY");field.setAccessible(true);var factory=(SavedData.Factory<DeferredItemDrops>)field.get(null);var queue=level.getDataStorage().get(factory,"thaumcraft_pending_inventory_drops");if(queue==null)return List.of();require(queue.quarantinedCount()==0,"no unaccounted quarantined output");var rows=new ArrayList<Object>();for(Object value:(Iterable<?>)BookClientSmoke.field(queue,"pending"))rows.add(value);Object flight=BookClientSmoke.field(queue,"inFlight");if(flight!=null && !(boolean)BookClientSmoke.field(flight,"accepted"))rows.add(BookClientSmoke.field(flight,"entry"));Set<UUID> settled=(Set<UUID>)BookClientSmoke.field(queue,"settled");var receiptField=DeferredItemDrops.class.getDeclaredField("LIVE_RECEIPTS");receiptField.setAccessible(true);var receipts=((Map<ServerLevel,Set<UUID>>)receiptField.get(null)).getOrDefault(level,Set.of());var ids=new HashSet<UUID>();var out=new ArrayList<ItemStack>();for(Object row:rows){BlockPos source=(BlockPos)BookClientSmoke.field(row,"source");UUID id=(UUID)BookClientSmoke.field(row,"id");if(!ownedPosition(Vec3.atCenterOf(source)) || settled.contains(id) || receipts.contains(id))continue;require(ids.add(id),"one actual queue/in-flight owner per UUID");ItemStack actual=(ItemStack)BookClientSmoke.field(row,"stack");if(level.getEntity(id) instanceof ItemEntity item && !item.isRemoved() && ItemStack.matches(item.getItem(),actual))continue;out.add(actual.copy());}return List.copyOf(out);}catch(ReflectiveOperationException error){throw new IllegalStateException("Accepted queue pure-view layout changed; reconcile, never substitute save()/flush()",error);}}
    private void approachDrop(ServerPlayer player){require(dropId!=null && dropStack!=null && player.serverLevel().getEntity(dropId) instanceof ItemEntity item && ItemStack.matches(item.getItem(),dropStack),"same actual unmoved mined UUID until physical pickup");ItemEntity item=(ItemEntity)player.serverLevel().getEntity(dropId);
        // Retain root's accepted diagonals, existing support, noCollision and
        // actual native player-touch contact envelope. ONLY actor is teleported.
        double[] offsets={0,.8,-.8,1.05,-1.05,1.2,-1.2};for(int rise=0;rise<=3;rise++)for(double x:offsets)for(double z:offsets){Vec3 at=new Vec3(item.getX()+x,bench.getY()+rise,item.getZ()+z);AABB body=player.getBoundingBox().move(at.subtract(player.position()));BlockPos floor=BlockPos.containing(at.x,at.y-.01,at.z);if(!targetBounds().contains(at) || !player.level().noCollision(player,body) || player.level().getBlockState(floor).getCollisionShape(player.level(),floor).isEmpty() || !body.inflate(1,.5,1).intersects(item.getBoundingBox()))continue;report.put("native_same_UUID_pickup_approach",Map.of("UUID",dropId.toString(),"unmoved_item_at",item.position().toString(),"collision_checked_player_at",at.toString(),"existing_support",floor.toShortString(),"within_native_contact_envelope",true,"item_relocations_or_refunds",0));stand(player,at.x,at.y,at.z);return;}throw new IllegalStateException("No supported collision-free native contact approach to same stabilizer UUID "+item.position());}

    private void capture(int index){require(captures==index,"exact contiguous capture146-153");++captures;report.put("actual_captures_requested",captures);capture.accept(CAPTURES.get(index));}
    private boolean hand(Minecraft client,Predicate<ItemStack> wanted)throws ReflectiveOperationException{require(client.player.containerMenu==client.player.inventoryMenu,"native hand SWAP outside menus only");if(!wanted.test(client.player.getInventory().getItem(HAND_SLOT))){click(client,playerSlot(client,itemSlot(client.player,wanted)),HAND_SLOT,ClickType.SWAP);handChangedAt=client.player.tickCount;return false;}if(client.player.tickCount-handChangedAt<6)return false;select(client,HAND_SLOT);return true;}
    private boolean emptyHand(Minecraft client)throws ReflectiveOperationException{return hand(client,ItemStack::isEmpty);}
    private static void select(Minecraft client,int slot)throws ReflectiveOperationException{client.player.getInventory().selected=slot;var method=client.gameMode.getClass().getDeclaredMethod("ensureHasSentCarriedItem");method.setAccessible(true);method.invoke(client.gameMode);}
    private static int playerSlot(Minecraft client,int index){return client.player.containerMenu.slots.stream().filter(slot->slot.container==client.player.getInventory() && slot.getContainerSlot()==index).findFirst().orElseThrow().index;}
    private static void click(Minecraft client,int slot,int button,ClickType type){client.gameMode.handleInventoryMouseClick(client.player.containerMenu.containerId,slot,button,type,client.player);}
    private static void sendRotation(Minecraft client,Vec3 point){lookAt(client,point);client.player.connection.send(new ServerboundMovePlayerPacket.Rot(client.player.getYRot(),client.player.getXRot(),client.player.onGround()));}
    private boolean aimReady(Minecraft client,BlockPos pos,Direction face,Vec3 point){require(client.player.canInteractWithBlock(pos,0),"actual native Survival reach "+pos);sendRotation(client,point);if(!pos.equals(useAimPos) || face!=useAimFace || !point.equals(useAimPoint)){useAimPos=pos.immutable();useAimFace=face;useAimPoint=point;useAimStarted=client.player.tickCount;return false;}return client.player.tickCount-useAimStarted>=6;}
    private boolean use(Minecraft client,BlockPos pos,Direction face,Vec3 point){if(!aimReady(client,pos,face,point))return false;require(client.gameMode.useItemOn(client.player,InteractionHand.MAIN_HAND,new BlockHitResult(point,face,pos,false)).consumesAction(),"actual native C2S block use accepted "+pos+"/"+face);clearAim();return true;}
    private void clearAim(){useAimPos=null;useAimFace=null;useAimPoint=null;}
    private static void lookAt(Minecraft client,Vec3 point){Vec3 delta=point.subtract(client.player.getEyePosition());client.player.setYRot((float)Math.toDegrees(Math.atan2(-delta.x,delta.z)));client.player.yRotO=client.player.getYRot();client.player.setXRot((float)-Math.toDegrees(Math.atan2(delta.y,Math.hypot(delta.x,delta.z))));client.player.xRotO=client.player.getXRot();}
    private static void stand(ServerPlayer player,double x,double y,double z){var body=new AABB(x-.3,y+.001,z-.3,x+.3,y+1.8,z+.3);BlockPos floor=BlockPos.containing(x,y-.01,z);require(player.level().noCollision(player,body) && !player.level().getBlockState(floor).getCollisionShape(player.level(),floor).isEmpty(),"collision-checked actor camera on actual existing support");player.teleportTo(x,y,z);}
    private void nodeCamera(ServerPlayer player,BlockPos pos){stand(player,pos.getX()+.5,bench.getY(),pos.getZ()+2.6);}
    private void targetCamera(ServerPlayer player){stand(player,targetPos.getX()+.5,bench.getY(),targetPos.getZ()+3.1);}
    private Vec3 leverPoint(){return Vec3.atCenterOf(leverPos).add(0,0,-.3125);}
    private static void releaseKeys(Minecraft client){client.options.keyUse.setDown(false);client.options.keyAttack.setDown(false);client.options.keyShift.setDown(false);}
    private void releaseInputs(Minecraft client){releaseUse(client);aimNode=false;ClientTickEvent.CLIENT_PRE.unregister(nativeClientPre);releaseKeys(client);if(client.player!=null && client.gameMode!=null)client.gameMode.stopDestroyBlock();if(previousCamera!=null)client.options.setCameraType(previousCamera);}
    private static ItemEntity clientDrop(Minecraft client,UUID id){for(var entity:client.level.entitiesForRendering())if(entity instanceof ItemEntity item && item.getUUID().equals(id) && !item.isRemoved())return item;return null;}
    private static BlockPos serverSessionNode(ServerPlayer player,ItemStack wand){try{var field=ItemWandCasting.class.getDeclaredField("SERVER_NODE_USES");field.setAccessible(true);Object value=((Map<?,?>)field.get(null)).get(player);require(value!=null && BookClientSmoke.field(value,"hand")==InteractionHand.MAIN_HAND && BookClientSmoke.field(value,"stack")==wand,"actual SERVER node session exact hand/stack");return ((BlockPos)BookClientSmoke.field(value,"pos")).immutable();}catch(ReflectiveOperationException error){throw new IllegalStateException("Read-only actual wand node-session view needs reconciliation",error);}}
    private static boolean sameExceptVis(ItemStack first,ItemStack second){WandData aData=ItemWandCasting.data(first),bData=ItemWandCasting.data(second);if(!aData.rod().equals(bData.rod()) || !aData.cap().equals(bData.cap()))return false;ItemStack a=first.copy(),b=second.copy();a.remove(ThaumcraftContent.WAND_DATA.get());b.remove(ThaumcraftContent.WAND_DATA.get());return ItemStack.matches(a,b);}
    private static void verifyDebit(ItemStack before,ItemStack after,Map<String,Integer> price){require(sameExceptVis(before,after),"all payer non-vis components unchanged");for(String type:WandData.PRIMALS)require(ItemWandCasting.data(before).amount(type)-ItemWandCasting.data(after).amount(type)==price.getOrDefault(type,0),"EXACT actual recipe centivis debit "+type);}
    private static CompoundTag beTag(BlockEntity tile){return tile.saveWithFullMetadata(tile.getLevel().registryAccess()).copy();}
    private static Map<String,Integer> aspects(AspectList list){var out=new LinkedHashMap<String,Integer>();for(Aspect type:list.getAspects()){int n=list.getAmount(type);require(n>=0,"no negative node stock");if(n>0)out.put(type.getTag(),n);}return Map.copyOf(out);}
    private static Map<String,Integer> typedStock(List<ItemStack> stacks){var out=new LinkedHashMap<String,Integer>();for(ItemStack stack:stacks)if(stack.is(ThaumcraftContent.CRYSTAL_ESSENCE.get())){var data=ItemCrystalEssence.data(stack);require(data!=null && data.amounts().size()==1 && data.amounts().values().iterator().next()==1 && List.of("ignis","potentia").contains(data.firstTag()),"actual saved produced typed1 perITEM, not lazy/untyped/shard/ethereal data");out.merge(data.firstTag(),stack.getCount(),Integer::sum);}return Map.copyOf(out);}
    private static int sum(Map<String,Integer> values){return values.values().stream().mapToInt(Integer::intValue).sum();}
    private static boolean phial(ItemStack value,String type){return value.is(ThaumcraftContent.FILLED_PHIAL.get()) && ItemEssence.data(value)!=null && ItemEssence.data(value).tag().equals(type);}
    private static boolean gold(ItemStack value){return value.is(ThaumcraftContent.WAND.get()) && ItemWandCasting.data(value).rod().equals("greatwood") && ItemWandCasting.data(value).cap().equals("gold");}
    private static boolean primary(ItemStack value){return value.is(ThaumcraftContent.WAND.get()) && ItemWandCasting.data(value).rod().equals("silverwood") && ItemWandCasting.data(value).cap().equals("thaumium");}
    private static int itemSlot(Player player,Predicate<ItemStack> wanted){for(int i=0;i<36;i++)if(wanted.test(player.getInventory().getItem(i)))return i;throw new IllegalStateException("Missing actual finite stabilizer input/saved stack");}
    private static ItemStack stack(Player player,Predicate<ItemStack> wanted){return player.getInventory().getItem(itemSlot(player,wanted));}
    private static int count(Player player,Item item){return player.getInventory().items.stream().mapToInt(value->countStack(value,item)).sum();}
    private static int countStack(ItemStack value,Item item){return value.is(item)?value.getCount():0;}
    private static int emptyMain(Player player){for(int i=9;i<36;i++)if(player.getInventory().getItem(i).isEmpty())return i;throw new IllegalStateException("No genuinely empty main slot");}
